export const BIRTHDAY_PEOPLE=['蘇爺','蔡教授','最強秘書'];
export function birthdayPerson(seed='ENT'){let h=0;for(const c of seed)h=(Math.imul(h,31)+c.codePointAt(0))>>>0;return BIRTHDAY_PEOPLE[h%3];}
